"""Regression tests for the bounded sub-agent closing reminder.

Covers the defect where the reminder was seeded from the child's initial
prompt instead of its completed transcript, where malformed notes skipped
or falsely counted as recovery, where reminder attempts were not charged,
and where custom result instructions / strict workflow roles wrongly
received the generic reminder.
"""

import json

import pytest

from minicode.task_outcome import canonicalize_task_outcome
from minicode.tooling import ToolContext
import minicode.tools.task as task_module
from minicode.tools import task as task_tool

VALID_REPORT = json.dumps(
    {
        "resultVersion": 1,
        "summary": "found auth.py",
        "files": [{"path": "auth.py", "action": "read"}],
        "risks": [],
        "verification": {"status": "not_run", "checks": []},
    }
)


class _FakeNote:
    def __init__(self, content):
        self.content = content


class _FakeMailbox:
    def __init__(self):
        self.notes = {}

    def write(self, key, content):
        self.notes[key] = content

    def read(self, key):
        content = self.notes.get(key)
        return _FakeNote(content) if content is not None else None


def _turn(outcome_note=None, final="investigation answer", extra=None):
    """Build a fake run_agent_turn writing ``outcome_note`` (or not)."""

    def fake_run_agent_turn(**kwargs):
        messages = list(kwargs["messages"])
        mailbox = kwargs.get("subagent_mailbox")
        if outcome_note is not None and mailbox is not None:
            for key in (
                "subagent_result",
                *(k for k in mailbox.notes if k.startswith("subagent_result")),
            ):
                pass
            mailbox.write(kwargs.get("_result_key", "subagent_result"), outcome_note)
        result = messages + [{"role": "assistant", "content": final}]
        if extra:
            result = messages + list(extra) + [
                {"role": "assistant", "content": final}
            ]
        kwargs["outcome_capture"].record(canonicalize_task_outcome("success", 0))
        return result

    return fake_run_agent_turn


def _run(input_data, mailbox, monkeypatch, tmp_path, fake):
    captured: list = []
    monkeypatch.setattr(
        task_module, "run_agent_turn", _capture(captured, fake)
    )
    result = task_tool.run(
        input_data,
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
        ),
    )
    return result, captured


def _capture(captured, inner):
    def wrapper(**kwargs):
        captured.append(dict(kwargs))
        return inner(**kwargs)

    return wrapper


def test_reminder_seeds_completed_transcript_and_validates_recovery(
    monkeypatch, tmp_path
):
    mailbox = _FakeMailbox()

    # Main run: child explores (tool evidence) but never writes the note.
    def fake(**kwargs):
        messages = list(kwargs["messages"])
        if len(messages) == 1:  # main run: system + ... actually main prompt
            result = messages + [
                {"role": "assistant_tool_call", "content": "grep auth"},
                {"role": "tool", "content": "auth.py:1 def issue_token"},
                {"role": "assistant", "content": "auth.py handles tokens"},
            ]
        else:
            # Reminder: rewrite the note through the mailbox tool channel.
            mailbox.write(kwargs["_reminder_result_key"], VALID_REPORT)
            result = messages + [
                {"role": "assistant", "content": "typed result submitted"}
            ]
        kwargs["outcome_capture"].record(canonicalize_task_outcome("success", 0))
        return result

    captured: list = []
    monkeypatch.setattr(task_module, "run_agent_turn", _capture(captured, fake))

    result = task_tool.run(
        {
            "description": "explore auth",
            "prompt": "find auth code",
            "agent_type": "explore",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
        ),
    )
    assert result.ok, result.output
    # Exactly one bounded correction attempt.
    assert len(captured) == 2
    reminder_msgs = captured[1]["messages"]
    # The reminder carries the completed investigation, tool evidence included.
    assert {"role": "assistant_tool_call", "content": "grep auth"} in reminder_msgs
    assert {"role": "tool", "content": "auth.py:1 def issue_token"} in reminder_msgs
    assert {"role": "assistant", "content": "auth.py handles tokens"} in reminder_msgs
    # The reminder user message is last.
    assert reminder_msgs[-1]["role"] == "user"
    assert "MANDATORY typed result note is missing" in reminder_msgs[-1]["content"]
    assert "recovered via closing reminder" in result.output
    assert '"contractStatus":"reported"' in result.output


def test_malformed_note_gets_one_correction_then_explicit_fallback(
    monkeypatch, tmp_path
):
    mailbox = _FakeMailbox()

    def fake(**kwargs):
        messages = list(kwargs["messages"])
        if len(calls) == 1:
            mailbox.write("subagent_result", "not json at all")
        else:
            mailbox.write("subagent_result", '{"resultVersion": 1}')  # still bad
        calls += 1
        kwargs["outcome_capture"].record(canonicalize_task_outcome("success", 0))
        return messages + [
            {"role": "assistant", "content": "substantive findings here"}
        ]

    calls = [0]
    state = {"n": 0}

    def fake2(**kwargs):
        state["n"] += 1
        messages = list(kwargs["messages"])
        if state["n"] == 1:
            mailbox.write("subagent_result", "not json at all")
        else:
            mailbox.write("subagent_result", '{"resultVersion": 1}')
        kwargs["outcome_capture"].record(canonicalize_task_outcome("success", 0))
        return messages + [
            {"role": "assistant", "content": "substantive findings here"}
        ]

    captured: list = []
    monkeypatch.setattr(task_module, "run_agent_turn", _capture(captured, fake2))

    result = task_tool.run(
        {
            "description": "explore auth",
            "prompt": "find auth code",
            "agent_type": "explore",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
        ),
    )
    assert result.ok, result.output
    # Malformed notes also get exactly one bounded correction attempt.
    assert len(captured) == 2
    # Recovery is rejected: the human hand-back keeps the substantive
    # findings with an explicit fallback marker.
    assert "substantive findings here" in result.output
    assert '"contractStatus":"fallback"' in result.output
    assert "note not submitted despite one closing reminder" in result.output


def test_custom_result_instruction_never_receives_reminder(
    monkeypatch, tmp_path
):
    mailbox = _FakeMailbox()
    captured: list = []
    monkeypatch.setattr(
        task_module,
        "run_agent_turn",
        _capture(captured, _turn(None, final="custom format answer")),
    )

    result = task_tool.run(
        {
            "description": "explore auth",
            "prompt": "find auth code",
            "agent_type": "explore",
            "_result_instruction": "Report findings as a haiku.",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
        ),
    )
    assert result.ok, result.output
    assert len(captured) == 1
    assert "closing reminder" not in result.output


def test_workflow_phase_never_receives_generic_reminder(
    monkeypatch, tmp_path
):
    mailbox = _FakeMailbox()
    captured: list = []
    monkeypatch.setattr(
        task_module,
        "run_agent_turn",
        _capture(captured, _turn(None, final="workflow answer")),
    )

    result = task_tool.run(
        {
            "description": "phase work",
            "prompt": "do phase work",
            "agent_type": "explore",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
            _workflow_phase=True,
        ),
    )
    assert result.ok, result.output
    assert len(captured) == 1
    assert "closing reminder" not in result.output


def test_reminder_attempts_are_counted_on_top_of_main_run(
    monkeypatch, tmp_path
):
    mailbox = _FakeMailbox()

    class _Sink:
        def __init__(self):
            self.model_turns = 0
            self.tool_calls = 0

    sinks = []

    def fake(**kwargs):
        sink = kwargs["event_sink"]
        sinks.append(sink)
        messages = list(kwargs["messages"])
        sink.model_turns += 1
        if len(messages) == 1:
            result = messages + [
                {"role": "assistant", "content": "main answer"}
            ]
        else:
            sink.model_turns += 1  # reminder spends two turns
            mailbox.write(kwargs["_reminder_result_key"], VALID_REPORT)
            result = messages + [
                {"role": "assistant", "content": "reminder answer"}
            ]
        kwargs["outcome_capture"].record(canonicalize_task_outcome("success", 0))
        return result

    captured: list = []
    monkeypatch.setattr(task_module, "run_agent_turn", _capture(captured, fake))

    events = []

    class _EventSink:
        def emit(self, event):
            events.append(event)

        def __getattr__(self, name):
            return lambda *a, **k: None

    result = task_tool.run(
        {
            "description": "explore auth",
            "prompt": "find auth code",
            "agent_type": "explore",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
            _event_sink=_EventSink(),
        ),
    )
    assert result.ok, result.output
    assert len(captured) == 2
    # Both calls share one monotonic sink: prior history is not rebilled and
    # the reminder's own turns are added.
    assert sinks[0] is sinks[1]
    assert sinks[0].model_turns == 3
    observation = next(
        (e for e in events if getattr(e, "event", "") == "subagent.observation"),
        None,
    )
    if observation is not None:
        assert observation.data["modelTurns"] == 3


def test_valid_report_from_main_run_skips_reminder(monkeypatch, tmp_path):
    mailbox = _FakeMailbox()
    captured: list = []
    monkeypatch.setattr(
        task_module,
        "run_agent_turn",
        _capture(
            captured,
            _turn(
                VALID_REPORT,
                final="done",
                extra=[{"role": "assistant_tool_call", "content": "tool use"}],
            ),
        ),
    )

    result = task_tool.run(
        {
            "description": "explore auth",
            "prompt": "find auth code",
            "agent_type": "explore",
        },
        ToolContext(
            cwd=str(tmp_path),
            _runtime={"model": "fake"},
            _subagent_mailbox=mailbox,
        ),
    )
    assert result.ok, result.output
    assert len(captured) == 1
    assert "closing reminder" not in result.output
    assert '"contractStatus":"reported"' in result.output

